export const SCRIPT_TYPES = "import { SourceValue, OhlcData, WickExtension } from '@wicklib/core';\n\n/**\n * Version of the WickScript API surface.\n */\ndeclare const WICKSCRIPT_API_VERSION = 1;\n/**\n * Error code used by unimplemented Phase 1 stubs.\n */\ndeclare const SCRIPT_NOT_IMPLEMENTED = \"WICKLIB_NOT_IMPLEMENTED\";\n\n/**\n * Declares the value produced by a script input.\n */\ninterface NumberScriptInput {\n    readonly type: \"number\";\n    readonly title?: string;\n    readonly defaultValue: number;\n    readonly min?: number;\n    readonly max?: number;\n    readonly step?: number;\n}\n/**\n * Declares a boolean script input.\n */\ninterface BooleanScriptInput {\n    readonly type: \"boolean\";\n    readonly title?: string;\n    readonly defaultValue: boolean;\n}\n/**\n * Declares a string script input.\n */\ninterface StringScriptInput {\n    readonly type: \"string\";\n    readonly title?: string;\n    readonly defaultValue: string;\n    readonly options?: readonly string[];\n}\n/**\n * Declares an OHLC source input.\n */\ninterface SourceScriptInput {\n    readonly type: \"source\";\n    readonly title?: string;\n    readonly defaultValue: SourceValue;\n    readonly options?: readonly SourceValue[];\n}\n/**\n * One declared script input.\n */\ntype ScriptInputDefinition = NumberScriptInput | BooleanScriptInput | StringScriptInput | SourceScriptInput;\n/**\n * A script's declared inputs.\n */\ntype ScriptInputMap = Readonly<Record<string, ScriptInputDefinition>>;\n/**\n * Resolved input values inferred from their declarations.\n */\ntype ScriptInputValues<TInputs extends ScriptInputMap> = {\n    readonly [K in keyof TInputs]: TInputs[K] extends NumberScriptInput ? number : TInputs[K] extends BooleanScriptInput ? boolean : TInputs[K] extends SourceScriptInput ? SourceValue : string;\n};\n/**\n * Supported plot renderers.\n */\ntype ScriptPlotType = \"line\" | \"histogram\" | \"area\";\n/**\n * Declares one stable script output series.\n */\ninterface ScriptPlotDefinition {\n    readonly id: string;\n    readonly title: string;\n    readonly type: ScriptPlotType;\n    readonly color?: string;\n    readonly lineWidth?: number;\n}\n/**\n * Union of plot ids declared by a script.\n */\ntype ScriptPlotId<TPlots extends readonly ScriptPlotDefinition[]> = TPlots[number][\"id\"];\n/**\n * Per-bar context passed to {@link ScriptDefinition.onBar}.\n */\ninterface ScriptContext<TInputs extends ScriptInputMap = ScriptInputMap, TPlotId extends string = string> {\n    /** Current OHLCV bar. */\n    readonly bar: Readonly<OhlcData>;\n    /** Zero-based index across the replay and subsequent streamed bars. */\n    readonly index: number;\n    /** Resolved, immutable inputs. */\n    readonly inputs: ScriptInputValues<TInputs>;\n    /** Persistent state for the current script run. */\n    readonly state: Map<string, unknown>;\n    /** Emits one value for the current bar. */\n    plot(seriesId: TPlotId, value: number | null): void;\n    /** Emits an alert for the current bar. */\n    alert(message: string): void;\n}\n/**\n * A complete script definition returned by {@link defineScript}.\n */\ninterface ScriptDefinition<TInputs extends ScriptInputMap = ScriptInputMap, TPlots extends readonly ScriptPlotDefinition[] = readonly ScriptPlotDefinition[]> {\n    readonly name?: string;\n    readonly inputs: TInputs;\n    readonly plots: TPlots;\n    readonly onBar: (context: ScriptContext<TInputs, ScriptPlotId<TPlots>>) => void;\n}\n/**\n * Declares a WickScript entry point.\n *\n * Scripts must export the returned definition as their default export.\n */\ndeclare function defineScript<const TInputs extends ScriptInputMap, const TPlots extends readonly ScriptPlotDefinition[]>(definition: ScriptDefinition<TInputs, TPlots>): ScriptDefinition<TInputs, TPlots>;\n\n/**\n * Resource limits for a sandboxed script.\n */\ninterface ScriptSandboxOptions {\n    memoryLimitBytes?: number;\n    maxStackSizeBytes?: number;\n    timeLimitMs?: number;\n    maxInterrupts?: number;\n    maxAlertsPerBar?: number;\n    maxAlertLength?: number;\n}\n/**\n * Resolved input values passed into a script.\n */\ntype ScriptSandboxInputs = Readonly<Record<string, number | boolean | string>>;\n/**\n * Plot and alert output from a sandbox run.\n */\ninterface ScriptSandboxResult {\n    plots: Readonly<Record<string, ReadonlyArray<number | null>>>;\n    alerts: ReadonlyArray<string>;\n}\ninterface ScriptSandboxMetadata {\n    name?: string;\n    inputs: Record<string, {\n        type: string;\n        defaultValue?: unknown;\n        min?: number;\n        max?: number;\n    }>;\n    plots: Array<{\n        id: string;\n        title: string;\n        type: string;\n    }>;\n}\n\n/**\n * Requests accepted by the WickScript worker.\n */\ntype ScriptWorkerRequest = {\n    type: \"compile\";\n    requestId: number;\n    source: string;\n    inputs?: ScriptSandboxInputs;\n    options?: ScriptSandboxOptions;\n} | {\n    type: \"run\";\n    requestId: number;\n    sessionId: number;\n    bars: readonly OhlcData[];\n} | {\n    type: \"dispose\";\n    requestId: number;\n    sessionId: number;\n};\n/**\n * Serializable failures returned by the WickScript worker.\n */\ninterface SerializedScriptError {\n    name: string;\n    message: string;\n    code?: string;\n    barIndex?: number | null;\n}\n/**\n * Responses emitted by the WickScript worker.\n */\ntype ScriptWorkerResponse = {\n    type: \"compiled\";\n    requestId: number;\n    sessionId: number;\n    metadata: ScriptSandboxMetadata;\n} | {\n    type: \"result\";\n    requestId: number;\n    result: ScriptSandboxResult;\n} | {\n    type: \"disposed\";\n    requestId: number;\n} | {\n    type: \"error\";\n    requestId: number;\n    error: SerializedScriptError;\n};\n\n/**\n * Resolved input values supplied by the host.\n */\ntype ScriptInputs = Readonly<Record<string, number | boolean | string>>;\n/**\n * Execution limits for a script session.\n */\ninterface ScriptLimits {\n    memoryLimitBytes?: number;\n    maxStackSizeBytes?: number;\n    timeLimitMs?: number;\n    maxInterrupts?: number;\n    maxAlertsPerBar?: number;\n    maxAlertLength?: number;\n}\n/**\n * Options for compiling a script.\n */\ninterface ScriptCompileOptions {\n    inputs?: ScriptInputs;\n    limits?: ScriptLimits;\n}\n/**\n * Metadata declared by a script.\n */\ninterface ScriptMetadata {\n    name?: string;\n    inputs: ScriptInputMap;\n    plots: readonly ScriptPlotDefinition[];\n}\n/**\n * Output of a completed replay or stream step.\n */\ninterface ScriptResult {\n    plots: Readonly<Record<string, ReadonlyArray<number | null>>>;\n    alerts: ReadonlyArray<string>;\n}\n/**\n * A compiled script session.\n */\ninterface CompiledScript {\n    readonly metadata: ScriptMetadata;\n    /** Runs a bar history through the script and returns all outputs for those bars. */\n    replay(bars: readonly OhlcData[]): Promise<ScriptResult>;\n    /** Runs one realtime bar through the same execution path as replay. */\n    stream(bar: OhlcData): Promise<ScriptResult>;\n    dispose(): Promise<void>;\n}\n/**\n * Compiles and executes WickScript sources.\n */\ninterface ScriptRuntime {\n    compile(source: string, options?: ScriptCompileOptions): Promise<CompiledScript>;\n    dispose(): void;\n}\ninterface ScriptWorkerPort {\n    postMessage(message: ScriptWorkerRequest): void;\n    addEventListener(type: \"message\", listener: (event: MessageEvent<ScriptWorkerResponse>) => void): void;\n    removeEventListener(type: \"message\", listener: (event: MessageEvent<ScriptWorkerResponse>) => void): void;\n    terminate?(): void;\n}\n/**\n * Creates a script runtime backed by a WickScript worker.\n *\n * The caller owns worker construction; use the `@wicklib/script/worker` entry with the\n * bundler's worker helper.\n */\ndeclare function createScriptWorkerRuntime(worker: ScriptWorkerPort): ScriptRuntime;\n\n/**\n * Machine-readable WickScript failure codes.\n */\ntype ScriptErrorCode = \"INVALID_API_VERSION\" | \"INVALID_SOURCE\" | \"UNSUPPORTED_IMPORT\" | \"UNSUPPORTED_GLOBAL\" | \"UNSUPPORTED_SYNTAX\" | \"INVALID_ENTRY\" | \"INVALID_DEFINITION\";\n/**\n * Typed error raised while validating or compiling a WickScript source.\n */\ndeclare class ScriptError extends Error {\n    readonly code: ScriptErrorCode;\n    readonly line?: number;\n    readonly column?: number;\n    constructor(code: ScriptErrorCode, message: string, location?: {\n        line: number;\n        column: number;\n    });\n}\n\n/**\n * Runtime failure codes for a sandboxed script.\n */\ntype ScriptRuntimeErrorCode = \"RUNTIME_ERROR\" | \"TIMEOUT\" | \"MEMORY_LIMIT\" | \"OUTPUT_LIMIT\" | \"INVALID_INPUT\" | \"REVISION_UNSUPPORTED\";\n/**\n * A failure raised while executing a compiled script.\n */\ndeclare class ScriptRuntimeError extends Error {\n    readonly code: ScriptRuntimeErrorCode;\n    readonly barIndex: number | null;\n    constructor(code: ScriptRuntimeErrorCode, message: string, barIndex?: number | null);\n}\n\n/**\n * A price source or a constant number accepted by a `ta.*` function.\n */\ntype TaSeries = SourceValue | number;\n/**\n * Deterministic technical-analysis helpers available inside WickScript.\n */\ninterface ScriptTa {\n    sma(context: ScriptContext, source: TaSeries, length: number): number | null;\n    ema(context: ScriptContext, source: TaSeries, length: number): number | null;\n    rsi(context: ScriptContext, source: TaSeries, length: number): number | null;\n    atr(context: ScriptContext, length: number): number | null;\n    highest(context: ScriptContext, source: TaSeries, length: number): number | null;\n    lowest(context: ScriptContext, source: TaSeries, length: number): number | null;\n    stdev(context: ScriptContext, source: TaSeries, length: number): number | null;\n    change(context: ScriptContext, source: TaSeries, length?: number): number | null;\n    roc(context: ScriptContext, source: TaSeries, length?: number): number | null;\n    cum(context: ScriptContext, source: TaSeries): number | null;\n    vwma(context: ScriptContext, source: TaSeries, length: number): number | null;\n    tr(context: ScriptContext): number | null;\n    obv(context: ScriptContext): number | null;\n    linreg(context: ScriptContext, source: TaSeries, length: number): number | null;\n    barssince(context: ScriptContext, condition: boolean, key: string): number | null;\n    crossover(context: ScriptContext, first: TaSeries, second: TaSeries): boolean;\n    crossunder(context: ScriptContext, first: TaSeries, second: TaSeries): boolean;\n}\n/**\n * Type-facing `ta` object. Execution is provided by the QuickJS worker realm.\n */\ndeclare const ta: ScriptTa;\n\n/**\n * Validates a WickScript source without executing it.\n *\n * Throws {@link ScriptError} when the API header, imports, globals, syntax, or entry shape\n * violate the WickScript contract.\n */\ndeclare function validateScript(source: string): void;\n\n/**\n * Extension descriptor used to register a runtime with the core.\n */\ninterface ScriptRuntimeExtension extends WickExtension {\n    kind: \"script-runtime\";\n    runtime: ScriptRuntime;\n}\n/**\n * Whether a script-callable function is free or requires a commercial license.\n */\ntype ScriptFunctionLicense = \"free\" | \"pro\";\n/**\n * Metadata for a script-callable function.\n */\ninterface ScriptFunctionMeta {\n    name: string;\n    license: ScriptFunctionLicense;\n}\n/**\n * Implementation of a script-callable function.\n */\ntype ScriptFunctionImpl = (...args: ReadonlyArray<number>) => number;\n/**\n * Registers a script-callable function. `@wicklib/pro` uses this for premium `ta.*`\n * functions without making the script package depend on pro.\n */\ndeclare function registerScriptFunction(_name: string, _impl: ScriptFunctionImpl, _meta: ScriptFunctionMeta): void;\n/**\n * A bar accepted by the script runtime.\n */\ntype ScriptBar = OhlcData;\n\nexport { SCRIPT_NOT_IMPLEMENTED, ScriptError, ScriptRuntimeError, WICKSCRIPT_API_VERSION, createScriptWorkerRuntime, defineScript, registerScriptFunction, ta, validateScript };\nexport type { BooleanScriptInput, CompiledScript, NumberScriptInput, ScriptBar, ScriptCompileOptions, ScriptContext, ScriptDefinition, ScriptErrorCode, ScriptFunctionImpl, ScriptFunctionLicense, ScriptFunctionMeta, ScriptInputDefinition, ScriptInputMap, ScriptInputValues, ScriptInputs, ScriptLimits, ScriptMetadata, ScriptPlotDefinition, ScriptPlotId, ScriptPlotType, ScriptResult, ScriptRuntime, ScriptRuntimeErrorCode, ScriptRuntimeExtension, ScriptTa, ScriptWorkerPort, SourceScriptInput, StringScriptInput, TaSeries };\n";
